// Auto-trim transparent margins so every product cutout centers identically (Req: consistent 10px gap).
function trimImg(img){
  if(!img||img.dataset.tr==='1')return; img.dataset.tr='1';
  try{
    const w=img.naturalWidth,h=img.naturalHeight; if(!w||!h)return;
    const cv=document.createElement('canvas');cv.width=w;cv.height=h;
    const cx=cv.getContext('2d');cx.drawImage(img,0,0);
    const d=cx.getImageData(0,0,w,h).data;
    let t=h,l=w,r=0,b=0,found=false;
    for(let y=0;y<h;y++)for(let x=0;x<w;x++){if(d[(y*w+x)*4+3]>14){found=true;if(x<l)l=x;if(x>r)r=x;if(y<t)t=y;if(y>b)b=y;}}
    if(!found)return;
    const mw=Math.round((r-l)*.015)+1,mh=Math.round((b-t)*.015)+1;
    l=Math.max(0,l-mw);t=Math.max(0,t-mh);r=Math.min(w-1,r+mw);b=Math.min(h-1,b+mh);
    const tw=r-l+1,th=b-t+1,o=document.createElement('canvas');o.width=tw;o.height=th;
    o.getContext('2d').drawImage(cv,l,t,tw,th,0,0,tw,th);
    img.src=o.toDataURL('image/png');
  }catch(e){}
}
