function colorOf(it){
  const struct=new Set([it.cat,it.mid,it.grp,'']);
  if(it.finish && !struct.has(it.finish)) return it.finish;
  const tg=it.tags||[];
  for(let i=tg.length-1;i>=0;i--){ if(!struct.has(tg[i])) return tg[i]; }
  const toks=(it.name||'').split(/\s+/).filter(Boolean);
  return toks.length?toks[toks.length-1]:'';
}
